-- =============================================================
-- SALESTORM — PostgreSQL Schema
-- =============================================================
-- Conventions:
--   · All PKs: UUID generated by gen_random_uuid()
--   · audit fields: created_at / updated_at (TIMESTAMPTZ NOT NULL)
--   · version column on tables with optimistic-lock updates
--   · CHECK constraints enforce domain invariants in the DB tier
-- =============================================================

-- ── Extensions ────────────────────────────────────────────────
CREATE EXTENSION IF NOT EXISTS "pgcrypto";  -- gen_random_uuid()

-- ── CATEGORY ──────────────────────────────────────────────────
CREATE TABLE category (
    id          UUID        NOT NULL DEFAULT gen_random_uuid(),
    name        TEXT        NOT NULL,
    slug        TEXT        NOT NULL,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT pk_category      PRIMARY KEY (id),
    CONSTRAINT uq_category_slug UNIQUE (slug)
);

-- ── PRODUCT ───────────────────────────────────────────────────
CREATE TABLE product (
    id          UUID        NOT NULL DEFAULT gen_random_uuid(),
    category_id UUID        NOT NULL,
    name        TEXT        NOT NULL,
    sku         TEXT        NOT NULL,
    base_price  NUMERIC(12,2) NOT NULL,
    status      TEXT        NOT NULL DEFAULT 'ACTIVE',
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT pk_product         PRIMARY KEY (id),
    CONSTRAINT fk_product_cat     FOREIGN KEY (category_id) REFERENCES category(id),
    CONSTRAINT uq_product_sku     UNIQUE (sku),
    CONSTRAINT chk_product_price  CHECK (base_price > 0),
    CONSTRAINT chk_product_status CHECK (status IN ('ACTIVE','INACTIVE'))
);

-- ── SALE ──────────────────────────────────────────────────────
CREATE TABLE sale (
    id          UUID        NOT NULL DEFAULT gen_random_uuid(),
    product_id  UUID        NOT NULL,
    sale_price  NUMERIC(12,2) NOT NULL,
    total_units INT         NOT NULL,
    starts_at   TIMESTAMPTZ NOT NULL,
    ends_at     TIMESTAMPTZ NOT NULL,
    status      TEXT        NOT NULL DEFAULT 'DRAFT',
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT pk_sale          PRIMARY KEY (id),
    CONSTRAINT fk_sale_product  FOREIGN KEY (product_id) REFERENCES product(id),
    CONSTRAINT chk_sale_price   CHECK (sale_price > 0),
    CONSTRAINT chk_sale_units   CHECK (total_units > 0),
    CONSTRAINT chk_sale_window  CHECK (ends_at > starts_at),
    CONSTRAINT chk_sale_status  CHECK (status IN ('DRAFT','ACTIVE','CLOSED'))
);

-- ── INVENTORY ─────────────────────────────────────────────────
-- version column used for optimistic locking on sweeper updates.
CREATE TABLE inventory (
    id                 UUID NOT NULL DEFAULT gen_random_uuid(),
    product_id         UUID NOT NULL,
    sale_id            UUID NOT NULL,
    total_quantity     INT  NOT NULL,
    available_quantity INT  NOT NULL,
    reserved_quantity  INT  NOT NULL DEFAULT 0,
    version            INT  NOT NULL DEFAULT 0,
    updated_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT pk_inventory         PRIMARY KEY (id),
    CONSTRAINT fk_inv_product       FOREIGN KEY (product_id) REFERENCES product(id),
    CONSTRAINT fk_inv_sale          FOREIGN KEY (sale_id)    REFERENCES sale(id),
    CONSTRAINT uq_inv_sale_product  UNIQUE (sale_id, product_id),
    CONSTRAINT chk_inv_total        CHECK (total_quantity     > 0),
    CONSTRAINT chk_inv_available    CHECK (available_quantity >= 0),
    CONSTRAINT chk_inv_reserved     CHECK (reserved_quantity  >= 0),
    CONSTRAINT chk_inv_sum          CHECK (available_quantity + reserved_quantity <= total_quantity)
);

-- ── CUSTOMER ──────────────────────────────────────────────────
CREATE TABLE customer (
    id          UUID        NOT NULL DEFAULT gen_random_uuid(),
    email       TEXT        NOT NULL,
    name        TEXT        NOT NULL,
    phone       TEXT,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT pk_customer       PRIMARY KEY (id),
    CONSTRAINT uq_customer_email UNIQUE (email)
);

-- ── INVENTORY_RESERVATION ─────────────────────────────────────
-- idempotency_key = SHA256(customer_id || sale_id || product_id).
-- Unique constraint is the durable idempotency guarantee.
CREATE TABLE inventory_reservation (
    id              UUID        NOT NULL DEFAULT gen_random_uuid(),
    customer_id     UUID        NOT NULL,
    sale_id         UUID        NOT NULL,
    product_id      UUID        NOT NULL,
    inventory_id    UUID        NOT NULL,
    idempotency_key TEXT        NOT NULL,
    status          TEXT        NOT NULL DEFAULT 'RESERVED',
    expires_at      TIMESTAMPTZ NOT NULL,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT pk_reservation         PRIMARY KEY (id),
    CONSTRAINT fk_res_customer        FOREIGN KEY (customer_id)  REFERENCES customer(id),
    CONSTRAINT fk_res_sale            FOREIGN KEY (sale_id)      REFERENCES sale(id),
    CONSTRAINT fk_res_product         FOREIGN KEY (product_id)   REFERENCES product(id),
    CONSTRAINT fk_res_inventory       FOREIGN KEY (inventory_id) REFERENCES inventory(id),
    CONSTRAINT uq_reservation_idem    UNIQUE (idempotency_key),
    CONSTRAINT chk_reservation_status CHECK (status IN (
        'AVAILABLE','RESERVED','PAYMENT_PENDING',
        'CONFIRMED','SOLD','PAYMENT_FAILED','RELEASED'))
);

-- ── CART ──────────────────────────────────────────────────────
CREATE TABLE cart (
    id          UUID        NOT NULL DEFAULT gen_random_uuid(),
    customer_id UUID        NOT NULL,
    status      TEXT        NOT NULL DEFAULT 'ACTIVE',
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT pk_cart         PRIMARY KEY (id),
    CONSTRAINT fk_cart_cust    FOREIGN KEY (customer_id) REFERENCES customer(id),
    CONSTRAINT chk_cart_status CHECK (status IN ('ACTIVE','CHECKED_OUT','ABANDONED'))
);

-- ── CART_ITEM ─────────────────────────────────────────────────
CREATE TABLE cart_item (
    id         UUID          NOT NULL DEFAULT gen_random_uuid(),
    cart_id    UUID          NOT NULL,
    product_id UUID          NOT NULL,
    quantity   INT           NOT NULL,
    unit_price NUMERIC(12,2) NOT NULL,
    CONSTRAINT pk_cart_item       PRIMARY KEY (id),
    CONSTRAINT fk_ci_cart         FOREIGN KEY (cart_id)    REFERENCES cart(id),
    CONSTRAINT fk_ci_product      FOREIGN KEY (product_id) REFERENCES product(id),
    CONSTRAINT uq_cart_item       UNIQUE (cart_id, product_id),
    CONSTRAINT chk_ci_quantity    CHECK (quantity   > 0),
    CONSTRAINT chk_ci_unit_price  CHECK (unit_price >= 0)
);

-- ── COUPON ────────────────────────────────────────────────────
CREATE TABLE coupon (
    id             UUID          NOT NULL DEFAULT gen_random_uuid(),
    code           TEXT          NOT NULL,
    discount_value NUMERIC(10,2) NOT NULL,
    discount_type  TEXT          NOT NULL,
    valid_from     TIMESTAMPTZ   NOT NULL,
    valid_until    TIMESTAMPTZ   NOT NULL,
    max_uses       INT           NOT NULL DEFAULT 1,
    used_count     INT           NOT NULL DEFAULT 0,
    created_at     TIMESTAMPTZ   NOT NULL DEFAULT now(),
    CONSTRAINT pk_coupon           PRIMARY KEY (id),
    CONSTRAINT uq_coupon_code      UNIQUE (code),
    CONSTRAINT chk_coupon_disc     CHECK (discount_value > 0),
    CONSTRAINT chk_coupon_type     CHECK (discount_type IN ('PERCENT','FIXED')),
    CONSTRAINT chk_coupon_window   CHECK (valid_until > valid_from),
    CONSTRAINT chk_coupon_max_uses CHECK (max_uses > 0)
);

-- ── ORDER ─────────────────────────────────────────────────────
CREATE TABLE "order" (
    id             UUID          NOT NULL DEFAULT gen_random_uuid(),
    customer_id    UUID          NOT NULL,
    reservation_id UUID,
    coupon_id      UUID,
    status         TEXT          NOT NULL DEFAULT 'CREATED',
    subtotal       NUMERIC(12,2) NOT NULL,
    discount       NUMERIC(12,2) NOT NULL DEFAULT 0,
    total          NUMERIC(12,2) NOT NULL,
    created_at     TIMESTAMPTZ   NOT NULL DEFAULT now(),
    updated_at     TIMESTAMPTZ   NOT NULL DEFAULT now(),
    CONSTRAINT pk_order              PRIMARY KEY (id),
    CONSTRAINT fk_order_customer     FOREIGN KEY (customer_id)    REFERENCES customer(id),
    CONSTRAINT fk_order_reservation  FOREIGN KEY (reservation_id) REFERENCES inventory_reservation(id),
    CONSTRAINT fk_order_coupon       FOREIGN KEY (coupon_id)      REFERENCES coupon(id),
    CONSTRAINT chk_order_status      CHECK (status IN (
        'CREATED','PAYMENT_PENDING','CONFIRMED','PROCESSING',
        'SHIPPED','OUT_FOR_DELIVERY','DELIVERED','CANCELLED')),
    CONSTRAINT chk_order_subtotal    CHECK (subtotal  >= 0),
    CONSTRAINT chk_order_discount    CHECK (discount  >= 0),
    CONSTRAINT chk_order_total       CHECK (total     >= 0)
);

-- ── ORDER_ITEM ────────────────────────────────────────────────
CREATE TABLE order_item (
    id         UUID          NOT NULL DEFAULT gen_random_uuid(),
    order_id   UUID          NOT NULL,
    product_id UUID          NOT NULL,
    quantity   INT           NOT NULL,
    unit_price NUMERIC(12,2) NOT NULL,
    CONSTRAINT pk_order_item      PRIMARY KEY (id),
    CONSTRAINT fk_oi_order        FOREIGN KEY (order_id)   REFERENCES "order"(id),
    CONSTRAINT fk_oi_product      FOREIGN KEY (product_id) REFERENCES product(id),
    CONSTRAINT chk_oi_quantity    CHECK (quantity   > 0),
    CONSTRAINT chk_oi_unit_price  CHECK (unit_price >= 0)
);

-- ── PAYMENT ───────────────────────────────────────────────────
-- idempotency_key unique constraint is the DB-layer guarantee against
-- double charges. Passed as X-Idempotency-Key to the payment gateway.
CREATE TABLE payment (
    id              UUID          NOT NULL DEFAULT gen_random_uuid(),
    order_id        UUID          NOT NULL,
    idempotency_key TEXT          NOT NULL,
    amount          NUMERIC(12,2) NOT NULL,
    status          TEXT          NOT NULL DEFAULT 'CREATED',
    gateway_ref     TEXT,
    failure_reason  TEXT,
    created_at      TIMESTAMPTZ   NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ   NOT NULL DEFAULT now(),
    CONSTRAINT pk_payment          PRIMARY KEY (id),
    CONSTRAINT fk_payment_order    FOREIGN KEY (order_id) REFERENCES "order"(id),
    CONSTRAINT uq_payment_idem     UNIQUE (idempotency_key),
    CONSTRAINT chk_payment_amount  CHECK (amount > 0),
    CONSTRAINT chk_payment_status  CHECK (status IN (
        'CREATED','PROCESSING','CONFIRMED','FAILED','PENDING_RECONCILE'))
);

-- ── SHIPMENT ──────────────────────────────────────────────────
CREATE TABLE shipment (
    id              UUID        NOT NULL DEFAULT gen_random_uuid(),
    order_id        UUID        NOT NULL,
    tracking_number TEXT,
    carrier         TEXT,
    status          TEXT        NOT NULL DEFAULT 'PENDING',
    shipped_at      TIMESTAMPTZ,
    delivered_at    TIMESTAMPTZ,
    CONSTRAINT pk_shipment         PRIMARY KEY (id),
    CONSTRAINT fk_shipment_order   FOREIGN KEY (order_id) REFERENCES "order"(id),
    CONSTRAINT uq_shipment_order   UNIQUE (order_id),
    CONSTRAINT chk_shipment_status CHECK (status IN (
        'PENDING','DISPATCHED','IN_TRANSIT','DELIVERED','RETURNED'))
);

-- ── NOTIFICATION ──────────────────────────────────────────────
CREATE TABLE notification (
    id          UUID        NOT NULL DEFAULT gen_random_uuid(),
    customer_id UUID        NOT NULL,
    order_id    UUID,
    channel     TEXT        NOT NULL,
    event_type  TEXT        NOT NULL,
    status      TEXT        NOT NULL DEFAULT 'PENDING',
    sent_at     TIMESTAMPTZ,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT pk_notification         PRIMARY KEY (id),
    CONSTRAINT fk_notif_customer       FOREIGN KEY (customer_id) REFERENCES customer(id),
    CONSTRAINT fk_notif_order          FOREIGN KEY (order_id)    REFERENCES "order"(id),
    CONSTRAINT chk_notif_channel       CHECK (channel    IN ('EMAIL','SMS','PUSH')),
    CONSTRAINT chk_notification_status CHECK (status     IN ('PENDING','SENT','FAILED'))
); 

-- ── OUTBOX_EVENT ──────────────────────────────────────────────
-- Written in the same DB transaction as the business operation.
-- Outbox Worker polls this table and publishes to SQS.
CREATE TABLE outbox_event (
    id             UUID        NOT NULL DEFAULT gen_random_uuid(),
    aggregate_type TEXT        NOT NULL,
    aggregate_id   TEXT        NOT NULL,
    event_type     TEXT        NOT NULL,
    payload        JSONB       NOT NULL,
    status         TEXT        NOT NULL DEFAULT 'PENDING',
    retry_count    INT         NOT NULL DEFAULT 0,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    published_at   TIMESTAMPTZ,
    CONSTRAINT pk_outbox        PRIMARY KEY (id),
    CONSTRAINT chk_outbox_status CHECK (status IN ('PENDING','PUBLISHED','FAILED'))
);

-- =============================================================
-- INDEXES
-- =============================================================

-- Inventory sweeper and fast lookup
CREATE INDEX idx_inventory_sale_product
    ON inventory(sale_id, product_id);

-- Reservation: sweeper query (partial — active reserved rows only)
CREATE INDEX idx_reservation_expiry
    ON inventory_reservation(expires_at)
    WHERE status = 'RESERVED';

-- Reservation: idempotency lookup (already covered by UNIQUE, listed for clarity)
-- uq_reservation_idem covers idempotency_key lookups.

-- Reservation: customer's reservation in a sale
CREATE INDEX idx_reservation_customer_sale
    ON inventory_reservation(customer_id, sale_id);

-- Payment: reconciler query (partial — pending rows only)
CREATE INDEX idx_payment_reconcile
    ON payment(created_at)
    WHERE status = 'PENDING_RECONCILE';

-- Order: customer order history
CREATE INDEX idx_order_customer_status
    ON "order"(customer_id, status);

-- Outbox: poller (partial — unpublished rows only)
CREATE INDEX idx_outbox_pending
    ON outbox_event(created_at)
    WHERE status = 'PENDING';

-- Notification: customer history
CREATE INDEX idx_notification_customer
    ON notification(customer_id, created_at DESC);
